import type { Node } from 'cleo'

/**
 * FPS example — shared data and helpers. A script MODULE: it exports, it is never attached to a node, and it
 * is evaluated once per game and shared (so it holds no per-node state; see `fps` below for the one global).
 *
 * Angles follow the engine's convention: yaw in degrees, 0 is +Z, counter-clockwise positive (a character's
 * RIGHT is a negative turn). A camera rig's pitch is positive DOWN.
 */

// ----- the weapons ------------------------------------------------------------------------------------

export interface WeaponSpec {
  key: string
  name: string
  /** Damage per bullet (per pellet for a shotgun). */
  damage: number
  /** Rounds per minute. */
  rpm: number
  /** Hold to keep firing. */
  auto: boolean
  mag: number
  reserve: number
  pellets: number
  /** Cone half-angle, degrees: hip, aimed down sights. Movement and crouch scale it (FpsPlayer.spreadNow). */
  hipSpread: number
  adsSpread: number
  /** Camera kick per shot, degrees (pitch up, yaw random +/-), and how fast it settles. */
  recoilPitch: number
  recoilYaw: number
  range: number
  /** Distance (m) over which damage falls to `falloff` of itself. */
  falloffRange: number
  falloff: number
  /** The aimed-down-sights field of view and the move speed scale while aimed. */
  adsFov: number
  adsMove: number
  /** Where the viewmodel sits when aimed (metres, in the camera's frame) for a weapon with no aim clip. */
  adsOffset: [number, number, number]
  /** Seconds, used where the clip's own length is not known yet. */
  reloadSeconds: number
  equipSeconds: number
  /** Whether the weapon has its own aimed clips (Idle/Walk/Fire aim variants). */
  hasAimClips: boolean
  /** Bots: how far from a target they will open fire, and their burst length. */
  botRange: number
  botBurst: [number, number]
}

export const WEAPONS: Record<string, WeaponSpec> = {
  pistol: {
    key: 'pistol', name: 'Pistol', damage: 26, rpm: 380, auto: false, mag: 12, reserve: 84, pellets: 1,
    hipSpread: 1.6, adsSpread: 0.25, recoilPitch: 1.5, recoilYaw: 0.45, range: 140, falloffRange: 70, falloff: 0.55,
    adsFov: 62, adsMove: 0.7, adsOffset: [0, 0, 0], reloadSeconds: 2.2, equipSeconds: 1.2, hasAimClips: true,
    botRange: 30, botBurst: [1, 3],
  },
  ak47: {
    key: 'ak47', name: 'AK-47', damage: 31, rpm: 600, auto: true, mag: 30, reserve: 150, pellets: 1,
    hipSpread: 2.6, adsSpread: 0.4, recoilPitch: 1.1, recoilYaw: 0.5, range: 220, falloffRange: 110, falloff: 0.6,
    adsFov: 52, adsMove: 0.6, adsOffset: [0, 0, 0], reloadSeconds: 4.4, equipSeconds: 1.6, hasAimClips: true,
    botRange: 45, botBurst: [3, 7],
  },
  shotgun: {
    key: 'shotgun', name: 'SAPS-12', damage: 12, rpm: 76, auto: false, mag: 6, reserve: 36, pellets: 9,
    hipSpread: 4.2, adsSpread: 2.6, recoilPitch: 4.2, recoilYaw: 0.9, range: 60, falloffRange: 22, falloff: 0.25,
    adsFov: 62, adsMove: 0.75, adsOffset: [-0.09, 0.045, 0.1], reloadSeconds: 3.6, equipSeconds: 1.1, hasAimClips: false,
    botRange: 16, botBurst: [1, 2],
  },
}

export const WEAPON_ORDER = ['pistol', 'ak47', 'shotgun']

// ----- the match --------------------------------------------------------------------------------------

export type FpsMode = 'ffa' | 'team2v2' | 'oneVsThree'

/**
 * The one global: the scene's Game Manager. Module state survives `Game.loadScene`, so the manager sets it in
 * `onStart` and clears it in `onDespawn`, and a combatant reads it through {@link manager} (never caches it).
 */
export const fps: { gm: any } = { gm: null }

/** The match's manager, or null when the scene has none (combatants then fall back to their own `team`). */
export function manager(): any {
  const gm = fps.gm
  return gm && gm.scene && !gm.markForRemoval ? gm : null
}

/** Whether `a` may hurt `b`: different teams, or the manager allows friendly fire. */
export function hostile(a: any, b: any): boolean {
  if (!a || !b || a === b) return false
  const gm = manager()
  if (gm) return gm.isHostile(a, b)
  return a.team !== b.team
}

/** Whether `a`'s bullets hurt `b`: hostile, or the manager has friendly fire on. */
export function canDamage(a: any, b: any): boolean {
  if (!a || !b || a === b) return false
  const gm = manager()
  return gm ? gm.canDamage(a, b) : a.team !== b.team
}

// ----- maths ------------------------------------------------------------------------------------------

export function clamp(v: number, lo: number, hi: number): number {
  return v < lo ? lo : v > hi ? hi : v
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t
}

/** Frame-rate independent approach: the share of the gap closed in `dt` at `rate` per second. */
export function approach(current: number, target: number, rate: number, dt: number): number {
  return current + (target - current) * (1 - Math.exp(-rate * dt))
}

export function planarDistance(a: ArrayLike<number>, b: ArrayLike<number>): number {
  return Math.hypot(b[0] - a[0], b[2] - a[2])
}

export function distance3(a: ArrayLike<number>, b: ArrayLike<number>): number {
  return Math.hypot(b[0] - a[0], b[1] - a[1], b[2] - a[2])
}

/** World yaw in degrees from `a` toward `b`. */
export function yawTo(a: ArrayLike<number>, b: ArrayLike<number>): number {
  return Math.atan2(b[0] - a[0], b[2] - a[2]) * 180 / Math.PI
}

/** Signed shortest difference `a - b` in degrees, in (-180, 180]. */
export function angleDiff(a: number, b: number): number {
  let d = (a - b) % 360
  if (d > 180) d -= 360
  else if (d <= -180) d += 360
  return d
}

/** The unit direction a camera rig looks along: yaw as above, pitch positive DOWN. */
export function aimDirection(yawDeg: number, pitchDeg: number, out: number[] = [0, 0, 0]): number[] {
  const y = yawDeg * Math.PI / 180, p = pitchDeg * Math.PI / 180
  const c = Math.cos(p)
  out[0] = Math.sin(y) * c
  out[1] = -Math.sin(p)
  out[2] = Math.cos(y) * c
  return out
}

/** A direction `coneDeg` off `dir` at most, uniformly over the cone's disc. */
export function spreadDirection(dir: ArrayLike<number>, coneDeg: number, out: number[] = [0, 0, 0]): number[] {
  const ang = Math.sqrt(Math.random()) * coneDeg * Math.PI / 180
  const roll = Math.random() * Math.PI * 2
  // An orthonormal basis around `dir`.
  let ux = 0, uy = 1, uz = 0
  if (Math.abs(dir[1]) > 0.95) { ux = 1; uy = 0 }
  let rx = dir[1] * uz - dir[2] * uy, ry = dir[2] * ux - dir[0] * uz, rz = dir[0] * uy - dir[1] * ux
  const rl = Math.hypot(rx, ry, rz) || 1
  rx /= rl; ry /= rl; rz /= rl
  const vx = ry * dir[2] - rz * dir[1], vy = rz * dir[0] - rx * dir[2], vz = rx * dir[1] - ry * dir[0]
  const s = Math.sin(ang), c = Math.cos(ang), cr = Math.cos(roll) * s, sr = Math.sin(roll) * s
  out[0] = dir[0] * c + rx * cr + vx * sr
  out[1] = dir[1] * c + ry * cr + vy * sr
  out[2] = dir[2] * c + rz * cr + vz * sr
  const l = Math.hypot(out[0], out[1], out[2]) || 1
  out[0] /= l; out[1] /= l; out[2] /= l
  return out
}

/** Euler degrees [pitch, yaw, 0] that turn a node's local +Y onto `normal` (decals project down their -Y). */
export function rotationOntoNormal(normal: ArrayLike<number>): number[] {
  const ny = clamp(normal[1], -1, 1)
  return [Math.acos(ny) * 180 / Math.PI, Math.atan2(normal[0], normal[2]) * 180 / Math.PI, 0]
}

// ----- nodes ------------------------------------------------------------------------------------------

/** The combatant (a node with `receiveHit` and the `fpsCombatant` variable) that owns `node`, or null. */
export function combatantOf(node: Node | null | undefined): any {
  for (let n: any = node; n; n = n.parent) if (n.getVariable?.('fpsCombatant')) return n
  return null
}

/** Every descendant of `root` (depth first), `fn` returning true stops the walk. */
export function walk(root: Node, fn: (n: Node) => boolean | void): void {
  const visit = (n: Node): boolean => {
    for (const c of n.children) { if (fn(c) === true) return true; if (visit(c)) return true }
    return false
  }
  visit(root)
}

export function findDescendant(root: Node, name: string): Node | null {
  let found: Node | null = null
  walk(root, n => { if (n.name === name) { found = n; return true } })
  return found
}

export function findByVariable(root: Node, variable: string): Node[] {
  const out: Node[] = []
  walk(root, n => { if ((n as any).getVariable?.(variable)) out.push(n) })
  return out
}

/** Play a SoundNode cue by name from the nearest `Sounds` group at or above `from`. Silent when absent. */
export function playCue(from: Node, name: string): void {
  for (let n: Node | null = from; n; n = n.parent) {
    const group = n.getChildByName('Sounds')[0]
    if (group) { (group.getChildByName(name)[0] as any)?.play?.(); return }
  }
}

import { CharacterNode, Logger } from 'cleo'
import type { Node, TemplateName } from 'cleo'
import { WEAPONS, aimDirection, canDamage, clamp, combatantOf, manager, rotationOntoNormal, spreadDirection } from '@/FPS/Scripts/FpsShared'
import type { WeaponSpec } from '@/FPS/Scripts/FpsShared'

/**
 * FPS example — what every fighter is: the player and each bot. A base script; FpsPlayer and FpsBot extend it.
 *
 * ## Taking a hit
 *
 * `receiveHit(damage, from, point, zone, dir)` is the one way damage arrives. It runs the same steps for
 * everyone and leaves the reaction to the subclass:
 *
 *   hp -= damage, then the blood at the point, then `onHurt`
 *   hp <= 0  ->  die(): the Game Manager is told (score, feed, respawn), then `onDeath` plays the end
 *
 * ## Shooting
 *
 * `fireHitscan` is the ONE bullet: a ray (with its spread), the first body it meets, the zone it struck (head
 * above `headLine` of the body's height), damage with falloff, and the effects — tracer, impact sparks, a
 * bullet hole on a wall, blood on a body. The player and the bots both shoot through it, so a bot's bullet
 * and the player's stop at the same things. A crouching body is only as tall as `crouchHeight`: a bullet
 * above it passes on, because the capsule underneath stays standing height.
 *
 * ## Teams
 *
 * `team` is just a string. The Game Manager (FpsGameManager) sets it from the match mode; with no manager in
 * the scene it is whatever the template says, and two combatants are hostile when their teams differ.
 */
export default class FpsCombatantNode extends CharacterNode {
  public displayName: string = 'Combatant'
  public team: string = 'red'
  public maxHp: number = 100
  public hp: number = 100
  /** Which WEAPONS entry this fighter uses. */
  public weapon: string = 'ak47'
  /** The template the Game Manager respawns this fighter from (blank: this node itself is reset instead). */
  public respawnTemplate: TemplateName = '' as TemplateName

  /** Damage multiplier for a head shot. */
  public headMultiplier: number = 2.2
  /** Height of the body standing and crouching, metres (hit zones, the eye, the target). */
  public standHeight: number = 1.78
  public crouchHeight: number = 1.2
  /** A hit above this share of the body's height is the head. */
  public headLine: number = 0.84

  // ----- effects: templates this fighter spawns --------------------------------------------------------
  public impactTemplate: TemplateName = 'FPS Impact' as TemplateName
  public bloodTemplate: TemplateName = 'FPS Blood Hit' as TemplateName
  public holeTemplate: TemplateName = 'FPS Bullet Hole' as TemplateName
  public tracerTemplate: TemplateName = 'FPS Tracer' as TemplateName

  // ----- runtime, read by others -----------------------------------------------------------------------
  public isDead: boolean = false
  public isCrouching: boolean = false
  public kills: number = 0
  public deaths: number = 0
  /** Where the last hit on this fighter came from (a world point), for the player's damage indicator. */
  public lastHitFrom: number[] = [0, 0, 0]
  public lastHitAt: number = -999
  /** The magazine, kept here so the HUD, the bots' reload and the manager's respawn all read one place. */
  public ammo: number = 30
  public reserve: number = 150

  protected _time: number = 0
  private _missing: Set<string> = new Set()

  // =================================================================================================
  // Lifecycle
  // =================================================================================================

  onStart() {
    this.setVariable('fpsCombatant', true, 'boolean', 'public')
    this.hp = this.maxHp
    this.isDead = false
    const spec = this.spec
    this.ammo = spec.mag
    this.reserve = spec.reserve
    manager()?.register?.(this)
  }

  onDespawn() {
    manager()?.unregister?.(this)
  }

  /** The current weapon's numbers. */
  public get spec(): WeaponSpec { return WEAPONS[this.weapon] ?? WEAPONS.ak47 }

  /** Height of the body now, metres. */
  public get bodyHeight(): number { return this.isCrouching ? this.crouchHeight : this.standHeight }

  /** Where a bullet leaves from and a bot sees from: world position, metres above the feet. */
  public get eyeOffset(): number { return this.bodyHeight - 0.13 }

  /** Where other fighters aim: the chest. */
  public get chest(): number[] {
    const p = this.worldPosition
    return [p[0], p[1] + this.bodyHeight * 0.68, p[2]]
  }

  // =================================================================================================
  // Damage
  // =================================================================================================

  /**
   * Take a hit. `zone` is 'head' | 'body'. Returns true when it landed. A subclass reacts in `onHurt`; the
   * kill is `die`.
   */
  public receiveHit(damage: number, from: Node | null, point?: ArrayLike<number>, zone: string = 'body', dir?: ArrayLike<number>): boolean {
    if (this.isDead || damage <= 0) return false
    this.hp = Math.max(0, this.hp - damage)
    const f = (from as any)?.worldPosition
    if (f) { this.lastHitFrom = [f[0], f[1], f[2]]; this.lastHitAt = this._time }
    const at = point ? [point[0], point[1], point[2]] : this.chest
    this._blood(at, dir)
    this.onHurt(damage, from, zone)
    manager()?.onDamaged?.(this, from, damage, zone)
    if (this.hp <= 0) this.die(from, zone, dir)
    return true
  }

  /** Every landed hit, before the death check. */
  protected onHurt(damage: number, from: Node | null, zone: string): void {}

  public die(from: Node | null, zone: string = 'body', dir?: ArrayLike<number>): void {
    if (this.isDead) return
    this.isDead = true
    this.deaths++
    const killer = combatantOf(from)
    if (killer && killer !== this) killer.kills++
    manager()?.onKilled?.(this, killer, zone)
    this.onDeath(killer, zone, dir)
  }

  /** The end: play the animation, ragdoll, drop the weapon. */
  protected onDeath(killer: any, zone: string, dir?: ArrayLike<number>): void {}

  /** Full health and a full magazine, alive again (the manager moves the body). */
  public resetForRespawn(): void {
    this.hp = this.maxHp
    this.isDead = false
    this.isCrouching = false
    const spec = this.spec
    this.ammo = spec.mag
    this.reserve = spec.reserve
  }

  // =================================================================================================
  // Shooting
  // =================================================================================================

  /** Where the muzzle is, for the tracer and the flash (a subclass places it at its weapon). */
  protected muzzleWorld(origin: number[]): number[] { return origin }

  /**
   * Fire one shot (all of a shotgun's pellets) from `origin` along `dir` with `coneDeg` of spread. Returns the
   * damage it dealt and whether it killed anyone. `damageScale` lets a bot's skill dull the weapon.
   */
  protected fireHitscan(origin: number[], dir: ArrayLike<number>, coneDeg: number, damageScale: number = 1)
    : { dealt: number, hits: number, headshot: boolean, killed: boolean } {
    const spec = this.spec
    const physics = this.scene?.physics as any
    const out = { dealt: 0, hits: 0, headshot: false, killed: false }
    if (!physics) return out
    const muzzle = this.muzzleWorld(origin)
    const per = new Map<any, { damage: number, zone: string, point: number[] }>()
    const pellets = Math.max(1, spec.pellets)
    manager()?.makeNoise?.(origin, spec.key === 'pistol' ? 38 : 60, this)

    for (let i = 0; i < pellets; i++) {
      const d = spreadDirection(dir, i === 0 && pellets === 1 ? coneDeg : coneDeg)
      let from = origin
      let ignore: any = null
      let hit: any = null
      for (let pass = 0; pass < 3; pass++) {
        const to = [from[0] + d[0] * spec.range, from[1] + d[1] * spec.range, from[2] + d[2] * spec.range]
        hit = physics.raycast(from, to, {
          reject: (owner: Node | null) => {
            const c = combatantOf(owner)
            return c === this || (ignore !== null && c === ignore)
          },
        })
        const victim = hit ? combatantOf(hit.node) : null
        // A crouching body is shorter than its capsule: a bullet above it goes on past.
        if (victim && victim.isCrouching && hit.point[1] - victim.worldPosition[1] > victim.crouchHeight + 0.02) {
          ignore = victim
          from = [hit.point[0] + d[0] * 0.02, hit.point[1] + d[1] * 0.02, hit.point[2] + d[2] * 0.02]
          continue
        }
        break
      }
      if (!hit) { this._tracer(muzzle, [origin[0] + d[0] * 80, origin[1] + d[1] * 80, origin[2] + d[2] * 80]); continue }
      this._tracer(muzzle, hit.point)
      const victim = combatantOf(hit.node)
      if (victim && !victim.isDead && canDamage(this, victim)) {
        const height = victim.bodyHeight
        const rel = (hit.point[1] - victim.worldPosition[1]) / Math.max(0.5, height)
        const zone = rel >= victim.headLine ? 'head' : 'body'
        const t = clamp(hit.distance / Math.max(1, spec.falloffRange), 0, 1)
        const dmg = spec.damage * (1 + (spec.falloff - 1) * t) * (zone === 'head' ? this.headMultiplier : 1) * damageScale
        const e = per.get(victim) ?? { damage: 0, zone: 'body', point: hit.point }
        e.damage += dmg
        if (zone === 'head') e.zone = 'head'
        e.point = hit.point
        per.set(victim, e)
        out.hits++
      } else if (victim && victim.isDead) {
        this._impact(hit, true)
      } else if (!victim) {
        this._impact(hit, false)
      } else {
        // A teammate (no friendly fire): the bullet stops, with the blood of a hit but no damage.
        this._blood(hit.point, d)
      }
    }
    for (const [victim, e] of per) {
      const wasDead = victim.isDead
      victim.receiveHit(e.damage, this, e.point, e.zone, dir)
      out.dealt += e.damage
      if (e.zone === 'head') out.headshot = true
      if (!wasDead && victim.isDead) out.killed = true
    }
    return out
  }

  // =================================================================================================
  // Effects
  // =================================================================================================

  /** Spawn an effect template, or nothing (quietly, once) when the scene has no such template. */
  protected spawnFx(template: string, position: ArrayLike<number>, rotation?: number[], parent?: Node): Node | null {
    if (!template || this._missing.has(template)) return null
    const scene = this.scene as any
    const node = scene?.instantiate(template, { position: [position[0], position[1], position[2]], ...(rotation ? { rotation } : {}), ...(parent ? { parent } : {}) })
    if (!node) {
      // instantiate has said which templates it knows; say once that this effect is skipped.
      this._missing.add(template)
      Logger.warn(`FPS: no "${template}" template, so that effect is skipped`, 'Script')
    }
    return node ?? null
  }

  private _impact(hit: any, onCorpse: boolean): void {
    const n = hit.normal
    const rot = rotationOntoNormal(n)
    const at = [hit.point[0] + n[0] * 0.015, hit.point[1] + n[1] * 0.015, hit.point[2] + n[2] * 0.015]
    this.spawnFx(this.impactTemplate, at, rot)
    if (!onCorpse) {
      const decal = this.spawnFx(this.holeTemplate, at, [rot[0], rot[1], Math.random() * 360])
      if (decal) manager()?.registerDecal?.(decal)
    }
  }

  private _blood(point: ArrayLike<number>, dir?: ArrayLike<number>): void {
    const yaw = dir ? Math.atan2(dir[0], dir[2]) * 180 / Math.PI : 0
    this.spawnFx(this.bloodTemplate, point, [0, yaw, 0])
  }

  private _tracer(from: number[], to: number[]): void {
    const dx = to[0] - from[0], dy = to[1] - from[1], dz = to[2] - from[2]
    const len = Math.hypot(dx, dy, dz)
    if (len < 3) return
    const node: any = this.spawnFx(this.tracerTemplate, from, [Math.atan2(-dy, Math.hypot(dx, dz)) * 180 / Math.PI, Math.atan2(dx, dz) * 180 / Math.PI, 0])
    if (node) { node.setVariable?.('tracerLength', len, 'number', 'public'); node.tracerLength = len }
  }

  /** Direction a camera rig at (yaw, pitch) looks along, handy for subclasses. */
  protected aim(yaw: number, pitch: number): number[] { return aimDirection(yaw, pitch) }
}

import { Game, Logger, Node } from 'cleo'
import { distance3, fps, findByVariable, planarDistance } from '@/FPS/Scripts/FpsShared'
import type { FpsMode } from '@/FPS/Scripts/FpsShared'

/**
 * FPS example — the match. Put ONE of these (the "FPS Game Manager" template) at the scene root and the
 * scene plays: it finds whatever combatants the scene holds, the player and any bot template instances,
 * deals them into teams by `mode`, puts them on the spawn points, scores kills, respawns the dead and ends
 * the match at the score or time limit. Nothing here knows the scene's geometry; it only reads three things
 * a scene may hold, all of them optional:
 *
 *   Spawn Point (template)   where fighters start and come back. None: they stay where they are placed.
 *   Cover Point (template)   a spot a bot may duck behind. None: bots find cover themselves (see bestCover).
 *   a baked Nav Mesh         bots walk it; without one they walk straight lines.
 *
 * ## Modes
 *
 *   ffa          everyone for themselves
 *   team2v2      two teams, split down the middle (the player and the first bot against the rest)
 *   oneVsThree   the player against everyone else (a scene with no player: the first fighter against the rest)
 *
 * ## For the other scripts
 *
 *   isHostile(a, b)         different teams (what a bot targets)
 *   canDamage(a, b)         hostile, or friendly fire is on
 *   makeNoise(pos, r, from) bots of other teams within `r` go and look
 *   callReinforcements(...) a team's idle bots within `reinforcementRadius` come to a point
 *   bestCover(...)          a spot out of a threat's sight, near a bot
 *   onKilled / onDamaged    the combatants report here
 *
 * It lives on its own node at the scene root, because its timers die with it.
 */
export default class FpsGameManagerNode extends Node {
  public mode: FpsMode = 'ffa'
  /** Team kills that win the match (0: none). */
  public scoreLimit: number = 20
  /** Minutes (0: none). */
  public timeLimit: number = 0
  public friendlyFire: boolean = false
  /** Seconds a fighter lies dead before it comes back. */
  public playerRespawnSeconds: number = 4
  public botRespawnSeconds: number = 6
  /** How long a bot's body stays before it fades. */
  public corpseSeconds: number = 9
  /** Seconds the match-over banner shows before the scene reloads. */
  public restartSeconds: number = 9
  /** Move every fighter onto a spawn point when the match starts (when the scene has spawn points). */
  public spawnAtStart: boolean = true
  /** Bullet holes kept in the world; older ones are removed. */
  public maxDecals: number = 90
  /** Bots of a team this close to a call for reinforcements answer it. */
  public reinforcementRadius: number = 55
  /** A spawn point this near a living enemy is passed over. */
  public spawnSafeDistance: number = 14

  // ----- runtime, read by the HUD ----------------------------------------------------------------------
  public matchOver: boolean = false
  public winner: string = ''
  public message: string = ''
  public timeLeft: number = 0
  public elapsed: number = 0

  private _fighters: Set<any> = new Set()
  private _scores: Map<string, number> = new Map()
  private _teamNames: Map<string, string> = new Map()
  private _decals: Node[] = []
  private _spawns: Node[] = []
  private _covers: Node[] = []
  private _started: boolean = false
  private _scan: number = 0
  private _feed: { text: string, until: number }[] = []
  private _usedSpawns: Set<Node> = new Set()
  private _snapshots: Map<any, any> = new Map()

  // =================================================================================================
  // Lifecycle
  // =================================================================================================

  onStart() {
    fps.gm = this
    this.setVariable('fpsManager', true, 'boolean', 'public')
    this.matchOver = false
    this.elapsed = 0
    this.timeLeft = this.timeLimit * 60
    // The fighters start on this same pass; deal them in just after.
    this.after(0.15, () => this._begin())
  }

  onDespawn() {
    if (fps.gm === this) fps.gm = null
  }

  onUpdate(delta: number) {
    this.elapsed += delta
    this._scan -= delta
    if (this._scan <= 0) { this._scan = 0.5; this._sweep() }
    this._feed = this._feed.filter(f => f.until > this.elapsed)
    if (this.matchOver || !this._started) return
    if (this.timeLimit > 0) {
      this.timeLeft = Math.max(0, this.timeLimit * 60 - this.elapsed)
      if (this.timeLeft <= 0) this._endMatch(this._leader())
    }
  }

  private _begin(): void {
    this._sweep()
    this._spawns = findByVariable(this.scene!.root, 'fpsSpawn')
    this._covers = findByVariable(this.scene!.root, 'fpsCover')
    this._assignTeams()
    if (this.spawnAtStart && this._spawns.length) {
      for (const f of this._ordered()) this._place(f, this._pickSpawn(f))
    }
    this._started = true
    this._announce(`${this._modeName()} - ${this._fighters.size} fighters`)
  }

  /** Register every combatant the scene holds that has not reported in. */
  private _sweep(): void {
    for (const c of this.scene?.characters ?? []) if ((c as any).getVariable?.('fpsCombatant')) this.register(c)
    for (const f of [...this._fighters]) if (!f.scene || f.markForRemoval) this._fighters.delete(f)
  }

  // =================================================================================================
  // Combatants and teams
  // =================================================================================================

  public register(c: any): void {
    if (this._fighters.has(c)) return
    this._fighters.add(c)
    // One that arrives mid-match (a respawn) joins the team it was given, or the smaller one.
    if (this._started && !this._snapshots.has(c)) this._joinLate(c)
  }

  public unregister(c: any): void { this._fighters.delete(c) }

  public get fighters(): any[] { return [...this._fighters] }

  /** The player first, then the bots in scene order: the order teams are dealt in. */
  private _ordered(): any[] {
    return [...this._fighters].sort((a, b) => (b.getVariable?.('isPlayer') ? 1 : 0) - (a.getVariable?.('isPlayer') ? 1 : 0))
  }

  private _assignTeams(): void {
    const list = this._ordered()
    const n = list.length
    this._teamNames.clear()
    list.forEach((f, i) => {
      let team: string
      if (this.mode === 'ffa') team = `solo-${i}`
      else if (this.mode === 'oneVsThree') team = i === 0 ? 'blue' : 'red'
      else team = i < Math.ceil(n / 2) ? 'blue' : 'red'
      f.team = team
      this._scores.set(team, 0)
      this._teamNames.set(team, this.mode === 'ffa' ? (f.displayName || `Fighter ${i + 1}`) : team === 'blue' ? 'Blue' : 'Red')
    })
  }

  private _joinLate(c: any): void {
    if (this.mode === 'ffa') {
      const team = `solo-${this._scores.size}`
      c.team = team
      this._scores.set(team, 0)
      this._teamNames.set(team, c.displayName || 'Fighter')
      return
    }
    const counts = new Map<string, number>()
    for (const f of this._fighters) if (f !== c) counts.set(f.team, (counts.get(f.team) ?? 0) + 1)
    if (this.mode === 'oneVsThree') c.team = 'red'
    else c.team = (counts.get('blue') ?? 0) <= (counts.get('red') ?? 0) ? 'blue' : 'red'
    if (!this._scores.has(c.team)) this._scores.set(c.team, 0)
  }

  public isHostile(a: any, b: any): boolean { return !!a && !!b && a !== b && a.team !== b.team }

  public canDamage(a: any, b: any): boolean {
    if (!a || !b || a === b) return false
    return a.team !== b.team || this.friendlyFire
  }

  public teamName(team: string): string { return this._teamNames.get(team) ?? team }

  public scoreOf(team: string): number { return this._scores.get(team) ?? 0 }

  /** [team, score] best first. */
  public standings(): { team: string, name: string, score: number }[] {
    return [...this._scores].map(([team, score]) => ({ team, name: this.teamName(team), score })).sort((a, b) => b.score - a.score)
  }

  private _modeName(): string {
    return this.mode === 'ffa' ? 'Free for all' : this.mode === 'team2v2' ? 'Team deathmatch' : 'One against all'
  }

  private _leader(): string {
    const s = this.standings()
    return s.length ? (s.length > 1 && s[0].score === s[1].score ? 'Draw' : s[0].name) : 'Draw'
  }

  // =================================================================================================
  // Kills, score, respawn
  // =================================================================================================

  public onDamaged(victim: any, attacker: any, damage: number, zone: string): void {
    attacker?.hitMarker?.(zone, victim.isDead)
  }

  public onKilled(victim: any, killer: any, zone: string): void {
    if (this.matchOver) return
    if (killer && killer !== victim && killer.team !== victim.team) {
      const total = this.scoreOf(killer.team) + 1
      this._scores.set(killer.team, total)
      this._feed.push({ text: `${killer.displayName} > ${victim.displayName}${zone === 'head' ? '  [headshot]' : ''}`, until: this.elapsed + 6 })
      if (this.scoreLimit > 0 && total >= this.scoreLimit) { this._endMatch(this.teamName(killer.team)); return }
    } else {
      // A kill by a teammate or by the world costs the victim's team a point.
      this._scores.set(victim.team, this.scoreOf(victim.team) - 1)
      this._feed.push({ text: `${victim.displayName} died`, until: this.elapsed + 6 })
    }
    const isPlayer = !!victim.getVariable?.('isPlayer')
    const delay = isPlayer ? this.playerRespawnSeconds : this.botRespawnSeconds
    if (isPlayer) victim.respawnIn = delay
    this._snapshots.set(victim, { team: victim.team, weapon: victim.weapon, displayName: victim.displayName, template: victim.respawnTemplate, skill: victim.skill })
    this.after(delay, () => this._respawn(victim))
  }

  private _respawn(victim: any): void {
    if (this.matchOver) return
    const spawn = this._pickSpawn(victim)
    if (victim.getVariable?.('isPlayer') || !victim.respawnTemplate) {
      // The player (and any fighter without a template) is reset in place.
      if (!victim.scene) return
      victim.resetForRespawn()
      this._place(victim, spawn)
      victim.respawned?.()
      return
    }
    const snap = this._snapshots.get(victim)
    this._snapshots.delete(victim)
    const at = spawn ? Array.from(spawn.worldPosition as ArrayLike<number>) : Array.from(victim.worldPosition as ArrayLike<number>)
    const node: any = this.scene?.instantiate(victim.respawnTemplate as string, {
      position: at, rotation: [0, spawn ? this._yawOf(spawn) : 0, 0],
    })
    if (!node) return
    if (snap) {
      node.team = snap.team
      node.weapon = snap.weapon
      node.displayName = snap.displayName
      if (snap.skill !== undefined) node.skill = snap.skill
    }
    node.kills = victim.kills
    node.deaths = victim.deaths
    this._snapshots.set(node, snap)
    this.register(node)
    node.setWorldPosition?.(at)
  }

  private _yawOf(n: Node): number {
    const f = (n as any).worldForward
    return Math.atan2(f[0], f[2]) * 180 / Math.PI
  }

  private _place(f: any, spawn: Node | null): void {
    if (!spawn) return
    const at = spawn.worldPosition
    f.setWorldPosition([at[0], at[1] + 0.05, at[2]])
    f.setRotation([0, this._yawOf(spawn), 0])
    f.teleported?.(this._yawOf(spawn))
  }

  /** A spawn point away from living enemies, rotating through the rest so two fighters do not stack. */
  private _pickSpawn(f: any): Node | null {
    const points = this._spawns.filter(s => s.scene)
    if (!points.length) return null
    const enemies = [...this._fighters].filter(o => o !== f && !o.isDead && this.isHostile(f, o))
    const scored = points.map(p => {
      const pos = p.worldPosition
      let nearest = Infinity
      for (const e of enemies) nearest = Math.min(nearest, distance3(pos, e.worldPosition))
      const used = this._usedSpawns.has(p) ? -30 : 0
      return { p, score: Math.min(nearest, 60) + used + Math.random() * 8 }
    }).filter(s => enemies.length === 0 || s.score > this.spawnSafeDistance - 30).sort((a, b) => b.score - a.score)
    const pick = (scored[0] ?? { p: points[Math.floor(Math.random() * points.length)] }).p
    this._usedSpawns.add(pick)
    if (this._usedSpawns.size >= points.length) this._usedSpawns.clear()
    return pick
  }

  private _endMatch(winner: string): void {
    if (this.matchOver) return
    this.matchOver = true
    this.winner = winner
    this.message = winner === 'Draw' ? 'DRAW' : `${winner.toUpperCase()} WINS`
    this.after(this.restartSeconds, () => { Game.loadScene(Game.sceneName).catch(e => Logger.warn('FPS: could not restart the match: ' + e, 'Script')) })
  }

  // =================================================================================================
  // HUD helpers
  // =================================================================================================

  private _announce(text: string): void {
    this._feed.push({ text, until: this.elapsed + 5 })
  }

  public get feed(): string[] { return this._feed.map(f => f.text) }

  // =================================================================================================
  // Noise, reinforcements
  // =================================================================================================

  /** A gunshot: bots of other teams within `radius` go to look. */
  public makeNoise(at: ArrayLike<number>, radius: number, source: any): void {
    for (const f of this._fighters) {
      if (f === source || f.isDead || !f.hear || !this.isHostile(source, f)) continue
      if (distance3(at, f.worldPosition) <= radius) f.hear(at, source)
    }
  }

  /** A bot's cry for help: its team's bots in range that are not already fighting come to `at`. */
  public callReinforcements(team: string, at: ArrayLike<number>, caller: any): number {
    let answered = 0
    for (const f of this._fighters) {
      if (f === caller || f.isDead || f.team !== team || !f.respondTo) continue
      if (planarDistance(at, f.worldPosition) > this.reinforcementRadius) continue
      if (f.respondTo(at, caller)) answered++
    }
    if (answered) this._announce(`${caller.displayName} calls for help`)
    return answered
  }

  // =================================================================================================
  // Cover
  // =================================================================================================

  /**
   * A spot near `from` where `threat` (a world point) cannot see: the Cover Points the scene has, then
   * a ring of probes around `from`. Out of sight is a ray from the threat's eye to a point crouched height
   * above the spot that something blocks; a candidate is also kept within `maxDistance` and, with a navmesh,
   * reachable. The best is the nearest to `from`, with a bonus for being farther from the threat.
   */
  public bestCover(from: ArrayLike<number>, threat: ArrayLike<number>, maxDistance: number = 24): number[] | null {
    const physics = this.scene?.physics as any
    if (!physics) return null
    const eye = [threat[0], threat[1] + 1.55, threat[2]]
    const hidden = (p: number[]) => {
      const target = [p[0], p[1] + 1.0, p[2]]
      const hit = physics.raycast(eye, target, { reject: (owner: any) => !!owner?.getVariable?.('fpsCombatant') })
      return !!hit && distance3(hit.point, target) > 0.35
    }
    const candidates: number[][] = []
    for (const c of this._covers) if (c.scene) {
      const p = c.worldPosition
      if (planarDistance(from, p) <= maxDistance) candidates.push([p[0], p[1], p[2]])
    }
    // Probes: points on rings round the bot, set down on the ground.
    for (let ring = 1; ring <= 3; ring++) for (let i = 0; i < 10; i++) {
      const a = (i / 10 + ring * 0.07) * Math.PI * 2, r = 3 + ring * 3.5
      const x = from[0] + Math.sin(a) * r, z = from[2] + Math.cos(a) * r
      const ground = physics.raycast([x, from[1] + 2, z], [x, from[1] - 6, z])
      if (ground && ground.normal[1] > 0.7) candidates.push([ground.point[0], ground.point[1], ground.point[2]])
    }
    const ai = (this.scene as any)?.ai
    let best: number[] | null = null
    let bestScore = -Infinity
    for (const p of candidates) {
      if (!hidden(p)) continue
      const near = planarDistance(from, p)
      let reach = near
      if (ai?.hasNavigation) {
        const route = ai.findPath(ai.navMeshFor(null), from as any, p as any)
        if (!route || route.length === 0) continue
        let len = 0
        for (let i = 1; i < route.length; i++) len += distance3(route[i - 1], route[i])
        if (len > near * 2.2 + 4) continue
        reach = len
      }
      const score = -reach + 0.25 * planarDistance(threat, p)
      if (score > bestScore) { bestScore = score; best = p }
    }
    return best
  }

  // =================================================================================================
  // Decals
  // =================================================================================================

  /** Keep the world's bullet holes to `maxDecals`: the oldest is removed. */
  public registerDecal(decal: Node): void {
    this._decals.push(decal)
    while (this._decals.length > this.maxDecals) {
      const old = this._decals.shift()
      try { (old as any)?.remove?.({ immediate: true }) } catch { /* already gone */ }
    }
  }
}

import { CameraRigNode, Input, ModelNode, Node } from 'cleo'
import type { Animator } from 'cleo'
import FpsCombatantNode from '@/FPS/Scripts/FpsCombatant'
import { WEAPONS, aimDirection, approach, clamp, combatantOf, findByVariable, findDescendant, lerp, manager, playCue } from '@/FPS/Scripts/FpsShared'

/** One weapon's state in the player's hands. */
interface Slot { key: string, ammo: number, reserve: number, view: ModelNode | null, muzzle: Node | null }

/**
 * FPS example — the player. The Character at the root of the "FPS Player" template, with a first-person camera
 * rig, the weapons' viewmodels under the camera, and a HUD. The Controller (last child) moves and looks; this
 * script does everything else:
 *
 *   crouch    hold Crouch: slower, the eye drops, and the body is only `crouchHeight` tall to a bullet
 *   sprint    hold Sprint: run speed; not while aiming, firing, reloading or crouched
 *   aim       hold Aim: field of view narrows, the weapon comes to the centre (its own aim clips, or a
 *             shift of the viewmodel where it has none), spread tightens, move speed falls
 *   fire      Fire: hip fire or aimed; semi-automatic weapons shoot once a press, automatic ones while held
 *   reload    Reload, or an empty magazine; a shotgun loads in three clips (start, shells, end)
 *   switch    1 2 3 or the wheel: the equip clip plays and the old weapon goes
 *
 * The weapons' animation is played straight on each viewmodel's animator by name (Idle, IdleAim, Walk,
 * WalkAim, Run, Fire, AimFire, Reload, Equip...): this script is the state machine, so a weapon with a clip
 * missing just keeps its idle.
 *
 * A bullet is `fireHitscan` (FpsCombatant): from the camera, along the rig's yaw and pitch, with the
 * current spread. The view recoils: a kick that mostly recovers, and a little shake.
 */
export default class FpsPlayerNode extends FpsCombatantNode {
  public displayName: string = 'Player'
  public team: string = 'blue'
  /** The weapons carried, in slot order (WEAPONS keys). */
  public loadout: string[] = ['ak47', 'pistol', 'shotgun']

  // ----- movement --------------------------------------------------------------------------------------
  public crouchSpeedScale: number = 0.5
  /** Seconds the eye takes to drop or rise. */
  public crouchSmoothing: number = 0.09
  public eyeStand: number = 1.66
  public eyeCrouch: number = 1.05

  // ----- the view --------------------------------------------------------------------------------------
  public hipFov: number = 78
  public sprintFovBoost: number = 5
  public adsSeconds: number = 0.14
  /** Mouse sensitivity share while aimed (1: the same). */
  public adsSensitivity: number = 0.55

  // ----- health ----------------------------------------------------------------------------------------
  public regenDelay: number = 5
  public regenPerSecond: number = 16

  // ----- runtime, read by the HUD ----------------------------------------------------------------------
  public ads: number = 0
  public reloading: boolean = false
  public sprinting: boolean = false
  public spreadNow: number = 0
  public respawnIn: number = 0
  public weaponIndex: number = 0
  public hitMarkerAt: number = -999
  public hitMarkerHead: boolean = false
  public hitMarkerKill: boolean = false

  private _rig: CameraRigNode | null = null
  private _slots: Slot[] = []
  private _viewmodels: Node | null = null
  private _anim: Animator | null = null
  private _clip: string = ''
  private _busyUntil: number = 0
  private _fireUntil: number = 0
  private _nextShot: number = 0
  private _reloadToken: number = 0
  private _bloom: number = 0
  private _pending: number = 0
  private _eye: number = 1.66
  private _fov: number = 78
  private _lastHurt: number = -999
  private _baseYawSens: number = 0
  private _basePitchSens: number = 0
  private _vmBase: number[] = [0, 0, 0]

  // =================================================================================================
  // Lifecycle
  // =================================================================================================

  onStart() {
    super.onStart()
    this.setVariable('isPlayer', true, 'boolean', 'public')
    this._rig = this._findRig()
    if (this._rig) {
      this._baseYawSens = this._rig.yawSensitivity
      this._basePitchSens = this._rig.pitchSensitivity
      this._eye = this.eyeStand
      this._fov = this.hipFov
    }
    this._viewmodels = this.getChildByName('Viewmodels')[0] ?? (this._rig?.camera ? findDescendant(this._rig.camera, 'Viewmodels') : null)
    const views = this._viewmodels ? findByVariable(this._viewmodels, 'fpsViewmodel') : []
    // Set here as well as in the template: whatever rebuilt a node from the library must not lose them.
    for (const v of views) { v.viewmodel = true; v.motionBlur = 'none' }
    this._slots = this.loadout.filter(k => WEAPONS[k]).map((key) => {
      const view = (views.find(v => v.getVariable('fpsViewmodel') === key) as ModelNode) ?? null
      return { key, ammo: WEAPONS[key].mag, reserve: WEAPONS[key].reserve, view, muzzle: view ? findDescendant(view, 'Muzzle') : null }
    })
    if (this._viewmodels) this._vmBase = Array.from(this._viewmodels.position as ArrayLike<number>)
    this.weaponIndex = 0
    this._select(0, false)
    this.hp = this.maxHp
  }

  private _findRig(): CameraRigNode | null {
    let rig: CameraRigNode | null = null
    const visit = (n: Node) => { for (const c of n.children) { if (!rig && c instanceof CameraRigNode) rig = c; else if (!rig) visit(c) } }
    visit(this)
    return rig
  }

  public get slot(): Slot { return this._slots[this.weaponIndex] }

  // =================================================================================================
  // The frame
  // =================================================================================================

  onUpdate(delta: number) {
    this._time += delta
    const intent = this.drive()
    if (!this._rig) return
    if (this.isDead) {
      intent.move[0] = 0; intent.move[1] = 0; intent.speedScale = 0
      this.respawnIn = Math.max(0, this.respawnIn - delta)
      this._deadCamera(delta)
      return
    }
    const gm = manager()
    if (gm?.matchOver) { intent.move[0] = 0; intent.move[1] = 0; return }

    const spec = this.spec
    const moving = this.planarSpeed > 0.4
    // ----- stance
    const wantCrouch = Input.pressed('Crouch')
    this.isCrouching = wantCrouch
    // ----- aim
    const wantAds = Input.pressed('Aim') && !this.reloading && this._time >= this._equipUntil()
    this.ads = approach(this.ads, wantAds ? 1 : 0, 1 / Math.max(0.03, this.adsSeconds) * 3, delta)
    this.sprinting = intent.sprint && moving && !wantCrouch && !wantAds && !(Input.pressed('Fire') && this._nextShot - this._time > -0.4) && !this.reloading
    intent.sprint = this.sprinting
    intent.speedScale = (wantCrouch ? this.crouchSpeedScale : 1) * lerp(1, spec.adsMove, this.ads)

    // ----- the camera: eye height, field of view, sensitivity
    this._eye = approach(this._eye, wantCrouch ? this.eyeCrouch : this.eyeStand, 1 / Math.max(0.02, this.crouchSmoothing) * 2.2, delta)
    const offset = this._rig.followOffset as any
    if (offset) offset[1] = this._eye
    const fovGoal = lerp(this.hipFov + (this.sprinting ? this.sprintFovBoost : 0), spec.adsFov, this.ads)
    this._fov = approach(this._fov, fovGoal, 14, delta)
    this._rig.fov = this._fov
    const sens = lerp(1, this.adsSensitivity, this.ads)
    this._rig.yawSensitivity = this._baseYawSens * sens
    this._rig.pitchSensitivity = this._basePitchSens * sens

    // ----- weapons
    this._switching()
    this._reloadInput()
    this._fireInput()
    this._recover(delta)
    this._viewmodelPose(delta, moving)
    this._viewmodelClearance(delta)
    this._viewmodelClip(moving)

    // ----- spread (read by the HUD's crosshair)
    this.spreadNow = this._spread(moving)
    this._bloom = Math.max(0, this._bloom - 5 * delta)

    // ----- health
    if (this._time - this._lastHurt > this.regenDelay && this.hp < this.maxHp) this.hp = Math.min(this.maxHp, this.hp + this.regenPerSecond * delta)
  }

  private _spread(moving: boolean): number {
    const spec = this.spec
    const base = lerp(spec.hipSpread, spec.adsSpread, this.ads)
    return base * (moving ? (this.sprinting ? 2.2 : 1.5) : 1) * (this.isCrouching ? 0.7 : 1) * (this.isGrounded ? 1 : 2.5) + this._bloom * (1 - this.ads * 0.6)
  }

  // =================================================================================================
  // Weapons
  // =================================================================================================

  /** Make slot `i` the weapon in hand; `play` runs its equip clip. */
  private _select(i: number, play: boolean = true): void {
    if (!this._slots.length) return
    const old = this.slot
    if (old) { old.ammo = this.ammo; old.reserve = this.reserve }
    this._reloadToken++
    this.reloading = false
    this.weaponIndex = ((i % this._slots.length) + this._slots.length) % this._slots.length
    const s = this.slot
    this.weapon = s.key
    for (const o of this._slots) if (o.view) o.view.visible = o === s
    this._anim = (s.view as any)?.animator ?? null
    this._clip = ''
    this.ammo = s.ammo
    this.reserve = s.reserve
    this._bloom = 0
    this._busyUntil = 0
    this._fireUntil = 0
    if (play) {
      const secs = this._playClip('Equip', false, s.view) ?? this.spec.equipSeconds
      this._busyUntil = this._time + Math.max(0.3, secs)
      playCue(this, 'Equip')
    }
  }

  private _equipUntil(): number { return this._busyUntil }

  private _switching(): void {
    let to = -1
    if (Input.started('Slot1')) to = 0
    else if (Input.started('Slot2')) to = 1
    else if (Input.started('Slot3')) to = 2
    else if (Input.started('NextWeapon')) to = this.weaponIndex + 1
    else if (Input.started('PrevWeapon')) to = this.weaponIndex - 1
    if (to < 0 || to >= 99) return
    to = ((to % this._slots.length) + this._slots.length) % this._slots.length
    if (to !== this.weaponIndex && this._slots[to]) this._select(to)
  }

  private _reloadInput(): void {
    const spec = this.spec
    if (this.reloading || this._time < this._busyUntil) return
    const want = Input.started('Reload') || (this.ammo <= 0 && Input.started('Fire'))
    if (want && this.ammo < spec.mag && this.reserve > 0) this._reload()
  }

  private _reload(): void {
    const spec = this.spec
    const slot = this.slot
    const token = ++this._reloadToken
    this.reloading = true
    this._fireUntil = 0
    playCue(this, 'Reload')
    const done = () => {
      if (token !== this._reloadToken) return
      const take = Math.min(spec.mag - this.ammo, this.reserve)
      this.ammo += take
      this.reserve -= take
    }
    const finish = () => { if (token === this._reloadToken) { this.reloading = false; this._clip = '' } }
    if (spec.key === 'shotgun') {
      const a = this._playClip('ReloadStart', false, slot.view) ?? 1
      this.after(a, () => {
        if (token !== this._reloadToken) return
        const b = this._playClip('Reload', false, slot.view) ?? 1.6
        this.after(b * 0.9, () => {
          if (token !== this._reloadToken) return
          done()
          const c = this._playClip('ReloadEnd', false, slot.view) ?? 0.9
          this._busyUntil = this._time + c
          this.after(c, finish)
        })
      })
    } else {
      const secs = this._playClip('Reload', false, slot.view) ?? spec.reloadSeconds
      this._busyUntil = this._time + secs
      this.after(secs * 0.82, done)
      this.after(secs, finish)
    }
  }

  private _fireInput(): void {
    const spec = this.spec
    if (this.reloading || this._time < this._busyUntil) return
    if (this.sprinting) return
    const trigger = spec.auto ? Input.pressed('Fire') : Input.started('Fire')
    if (!trigger || this._time < this._nextShot) return
    if (this.ammo <= 0) { this._nextShot = this._time + 0.25; playCue(this, 'Empty'); return }
    this._shoot()
  }

  private _shoot(): void {
    const spec = this.spec
    const rig = this._rig!
    const cam = rig.camera
    if (!cam) return
    this.ammo--
    this._nextShot = this._time + 60 / spec.rpm
    const p = cam.worldPosition
    const origin = [p[0], p[1], p[2]]
    const dir = aimDirection(rig.yaw, rig.pitch)
    const cone = this._spread(this.planarSpeed > 0.4)
    this.fireHitscan(origin, dir, cone, 1)
    this._bloom = Math.min(spec.hipSpread * 1.6, this._bloom + spec.hipSpread * 0.12)

    // The view kicks up and a little aside; most of the pitch comes back (_recover).
    const kick = spec.recoilPitch * (this.isCrouching ? 0.75 : 1) * (1 - this.ads * 0.35)
    rig.pitch = rig.pitch - kick
    rig.yaw = rig.yaw + (Math.random() - 0.5) * 2 * spec.recoilYaw
    this._pending += kick * 0.7
    rig.shake(spec.key === 'shotgun' ? 0.18 : 0.04)

    // The shot clip; held for most of its length, shorter than the shot interval so the idle returns between.
    const clip = this.ads > 0.5 && spec.hasAimClips ? 'AimFire' : 'Fire'
    const secs = this._playClip(clip, false, this.slot.view, true) ?? 0.4
    this._fireUntil = this._time + Math.min(secs * 0.9, 60 / spec.rpm * 1.1 + 0.05)
    this._flash()
    playCue(this, spec.key === 'pistol' ? 'ShotPistol' : spec.key === 'shotgun' ? 'ShotShotgun' : 'ShotRifle')
    if (spec.key === 'shotgun') this.after(0.35, () => { if (!this.reloading && !this.isDead) { const s = this.slot; this._playClip('Pump', false, s.view, true); this._fireUntil = this._time + 0.7 } })
  }

  protected muzzleWorld(origin: number[]): number[] {
    const m: any = this.slot?.muzzle
    const cam: any = this._rig?.camera
    if (!m?.worldPosition || !cam) return origin
    // The viewmodel is drawn through the camera's viewmodel lens and at a share of its true distance
    // (Node.viewmodel), so its muzzle is not where its node is: it is at the same point squeezed the way the
    // renderer squeezes it, about the camera and in its frame (x and y by lens x depth, z by depth).
    const w = m.worldPosition
    const t = cam.worldTransform
    const dx = w[0] - t[12], dy = w[1] - t[13], dz = w[2] - t[14]
    const x = t[0] * dx + t[1] * dy + t[2] * dz, y = t[4] * dx + t[5] * dy + t[6] * dz, z = t[8] * dx + t[9] * dy + t[10] * dz
    const k = this._vmDepth
    const f = Math.tan(this._fov * Math.PI / 360) / Math.tan(this.viewmodelFov * Math.PI / 360)
    const lx = x * f * k, ly = y * f * k, lz = z * k
    return [t[0] * lx + t[4] * ly + t[8] * lz + t[12], t[1] * lx + t[5] * ly + t[9] * lz + t[13], t[2] * lx + t[6] * ly + t[10] * lz + t[14]]
  }

  /** The lens the viewmodels are drawn at (the camera's `viewmodelFov`), degrees. */
  public viewmodelFov: number = 58
  /** How far in front of the camera the viewmodel reaches (its muzzle), metres: what a wall must leave room for. */
  public viewmodelReach: number = 0.95
  private _vmDepth: number = 1

  /**
   * Keep the weapon out of a wall: the share of its true distance the renderer draws the viewmodel at, from
   * the clearest of a few rays ahead. The weapon shrinks toward the camera along every view ray, so it stays
   * the same size on the screen and lies in front of the wall, lit as the place it is drawn at.
   */
  private _viewmodelClearance(delta: number): void {
    const cam: any = this._rig?.camera
    const physics: any = this.scene?.physics
    if (!cam || !physics) return
    cam.viewmodelFov = this.viewmodelFov
    const p = cam.worldPosition
    const t = cam.worldTransform
    // Camera-local +Z is forward, +X left, +Y up; a ray each for the centre and four points about it.
    const rays: number[][] = [[0, 0], [0.22, 0], [-0.22, 0], [0, 0.18], [0, -0.22]]
    let nearest = Infinity
    for (const [lx, ly] of rays) {
      const dir = [t[8] + t[0] * lx + t[4] * ly, t[9] + t[1] * lx + t[5] * ly, t[10] + t[2] * lx + t[6] * ly]
      const len = Math.hypot(dir[0], dir[1], dir[2])
      const reach = this.viewmodelReach + 0.1
      const hit = physics.raycast([p[0], p[1], p[2]], [p[0] + dir[0] / len * reach, p[1] + dir[1] / len * reach, p[2] + dir[2] / len * reach],
        { reject: (owner: Node | null) => combatantOf(owner) === this })
      if (hit) nearest = Math.min(nearest, hit.distance)
    }
    const want = nearest === Infinity ? 1 : clamp((nearest - 0.05) / this.viewmodelReach, 0.3, 1)
    // In fast (never through a wall), out a little slower.
    this._vmDepth = approach(this._vmDepth, want, want < this._vmDepth ? 40 : 9, delta)
    cam.viewmodelDepth = this._vmDepth
  }

  private _flash(): void {
    const cam: any = this._rig?.camera
    const at = this.muzzleWorld([0, 0, 0])
    if (!cam) return
    const f = this.spawnFx('FPS Muzzle Flash', at, [this._rig!.pitch, this._rig!.yaw, 0])
    void f
  }

  /** The view comes back down by a share of what the kick took, while no shot is firing. */
  private _recover(delta: number): void {
    if (this._pending <= 0.0005 || !this._rig) return
    const r = Math.min(this._pending, (this._pending * 6 + 0.4) * delta)
    this._rig.pitch = this._rig.pitch + r
    this._pending -= r
  }

  // =================================================================================================
  // The viewmodel
  // =================================================================================================

  /**
   * Fire the one-shot `name` on a viewmodel's animator (its Actions layer state of that name; a second fire while
   * it plays restarts it) and return how long it lasts in seconds, or undefined when the weapon has no such clip.
   * A weapon's graph is built by tools/fps/characters.mjs viewmodelMachine.
   */
  private _playClip(name: string, _loop: boolean, view: ModelNode | null, _restart: boolean = false): number | undefined {
    const anim: any = (view as any)?.animator
    const info = anim?.triggerInfo?.(name)
    if (!info) return undefined
    anim.setTrigger(name)
    this._clip = name
    return info.seconds > 0 ? info.seconds : info.clipLength
  }

  /** The base layer follows what the player is doing: Idle / IdleAim / Walk / WalkAim / Run, by three bools. */
  private _viewmodelClip(moving: boolean): void {
    const anim: any = (this.slot?.view as any)?.animator
    if (!anim) return
    anim.setBool('Moving', moving)
    anim.setBool('Sprinting', moving && this.sprinting)
    anim.setBool('Aim', this.ads > 0.4 && this.spec.hasAimClips)
  }

  /** A weapon with no aim clip comes to the centre by shifting the whole viewmodel group. */
  private _viewmodelPose(delta: number, moving: boolean): void {
    const g = this._viewmodels
    if (!g) return
    const spec = this.spec
    const shift = spec.hasAimClips ? [0, 0, 0] : spec.adsOffset
    const t = this.ads
    g.setPosition([this._vmBase[0] + shift[0] * t, this._vmBase[1] + shift[1] * t, this._vmBase[2] + shift[2] * t])
  }

  // =================================================================================================
  // Hurt, dead, alive
  // =================================================================================================

  protected onHurt(damage: number, from: Node | null, zone: string): void {
    this._lastHurt = this._time
    this._rig?.shake(clamp(damage / 80, 0.05, 0.35))
    playCue(this, 'Hurt')
  }

  protected onDeath(killer: any, zone: string): void {
    this.respawnIn = manager()?.playerRespawnSeconds ?? 0
    for (const s of this._slots) if (s.view) s.view.visible = false
    this.ads = 0
    this.reloading = false
    this._reloadToken++
    playCue(this, 'Death')
  }

  private _deadCamera(delta: number): void {
    const rig = this._rig!
    this._eye = approach(this._eye, 0.35, 5, delta)
    const offset = rig.followOffset as any
    if (offset) offset[1] = this._eye
    rig.fov = approach(rig.fov, 62, 3, delta)
  }

  /** The manager has moved the body onto a spawn point and reset health: back on its feet. */
  public respawned(): void {
    this.isCrouching = false
    this._eye = this.eyeStand
    this._pending = 0
    for (const s of this._slots) { s.ammo = WEAPONS[s.key].mag; s.reserve = WEAPONS[s.key].reserve }
    this._select(this.weaponIndex % Math.max(1, this._slots.length))
    this._rig?.snapToTarget()
  }

  /** The manager placed this body facing `yaw`: the camera faces the same way. */
  public teleported(yaw: number): void {
    this._rig?.setOrbit(yaw, 0)
    this._rig?.snapToTarget()
  }

  /** A shot of ours landed: the HUD flashes its hit marker. */
  public hitMarker(zone: string, killed: boolean): void {
    this.hitMarkerAt = this._time
    this.hitMarkerHead = zone === 'head'
    this.hitMarkerKill = killed
    playCue(this, killed ? 'Kill' : 'Hit')
  }

  public resetForRespawn(): void {
    super.resetForRespawn()
    this._lastHurt = -999
  }
}

import { Logger, ModelNode, Node, setMoveWorld } from 'cleo'
import type { Animator } from 'cleo'
import FpsCombatantNode from '@/FPS/Scripts/FpsCombatant'
import { angleDiff, clamp, combatantOf, distance3, findByVariable, findDescendant, hostile, manager, planarDistance, playCue, yawTo } from '@/FPS/Scripts/FpsShared'

/** The death clips, in the order the animator's `Die0..Die5` triggers play them. */
const DEATHS = ['DeathFromTheFront', 'DeathFromFrontHeadshot', 'DeathFromTheBack', 'DeathFromBackHeadshot', 'DeathFromRight', 'DeathCrouchingHeadshotFront']

type BotState = 'patrol' | 'search' | 'engage' | 'cover' | 'retreat' | 'dead'

/**
 * FPS example — a computer fighter. The enemy template's root script (the Character node): it senses,
 * decides and shoots, and the AI controller under it (Brain, source AI) only walks where it is told.
 *
 * ## What it does
 *
 *   patrol    wanders between spots near where it started, at a walk
 *   search    goes to where it last saw a target, or heard a shot, or was called to; looks round; gives up
 *   engage    a target in sight: holds a firing distance, strafes, crouches at range, shoots in bursts
 *   cover     hurt or under fire: runs to a spot the target cannot see (FpsGameManager.bestCover), crouches
 *             there and pops up to shoot
 *   retreat   badly hurt (below `retreatAt` of its health): runs for cover, calls its team for reinforcements,
 *             reloads and waits out of sight, then recovers a little and comes back
 *   dead      plays a random death clip (matched to where the shot came from), then goes ragdoll
 *
 * The Brain's behaviour graph only reads `navMode` (0 stand, 1 walk the nav mesh to `goalPoint`, 2 this script
 * moves the body) and does the pathing; everything else is here. Targets are the sightings the controller
 * reports, filtered on {@link hostile}: perception offers every character, and teams are this example's.
 *
 * Tunables are fields on the template, so a scene can make one bot lazier or deadlier by overriding them
 * on its instance.
 */
export default class FpsBotNode extends FpsCombatantNode {
  public displayName: string = 'Bot'
  /** 0..1: aim, reaction and how long it keeps its head up. */
  public skill: number = 0.55
  /** Sees this far, and across this cone (the full angle). */
  public sightRange: number = 55
  public sightAngle: number = 140
  /** Seconds between noticing a target and opening fire (the worse the skill, the longer). */
  public reactionSeconds: number = 0.45
  /** Walk and run speeds, metres a second. */
  public patrolSpeedScale: number = 0.42
  /** Below this share of health: seek cover. Below `retreatAt`: run for it and call for help. */
  public coverAt: number = 0.62
  public retreatAt: number = 0.3
  /** Health regained a second while out of combat. */
  public regenPerSecond: number = 3
  /** Probability of crouching while standing and shooting at long range. */
  public crouchChance: number = 0.45
  /** Seconds it waits behind cover before it looks. */
  public coverSeconds: number = 3.5
  /** Seconds the clip plays before the body goes ragdoll (0: the clip's length times `ragdollAt`). */
  public ragdollAt: number = 0.62
  public corpseSeconds: number = 8
  /** Damage multiplier for a bot's bullets against everyone. */
  public damageScale: number = 0.55
  /** Rounds a second as a share of the weapon's rate. */
  public fireRateScale: number = 0.7

  // ----- published for the Brain graph and the HUD -----------------------------------------------------
  public navMode: number = 0
  public state: BotState = 'patrol'
  public goalPoint: number[] = [0, 0, 0]
  /** Mirrors of the controller's blackboard, for the graph. */
  public hasThreat: boolean = false

  private _brain: any = null
  private _model: ModelNode | null = null
  private _animator: Animator | null = null
  private _weapons: Node[] = []
  private _muzzle: Node | null = null
  private _home: number[] = [0, 0, 0]

  private _target: any = null
  private _seenAt: number = -999
  private _noticedAt: number = -999
  private _lastKnown: number[] | null = null
  private _sees: boolean = false
  private _alert: number[] | null = null
  private _alertUntil: number = 0

  private _stateTime: number = 0
  private _wait: number = 0
  private _burst: number = 0
  private _nextShot: number = 0
  private _strafe: number = 1
  private _strafeUntil: number = 0
  private _crouching: boolean = false
  private _crouchUntil: number = 0
  private _reloading: number = 0
  private _coverPoint: number[] | null = null
  private _inCover: boolean = false
  private _calledAt: number = -999
  private _hurtAt: number = -999
  private _patrolWait: number = 0
  private _losTimer: number = 0
  private _pathTimer: number = 0
  private _sinceCombat: number = 99
  private _ammoClip: number = 0

  // =================================================================================================
  // Lifecycle
  // =================================================================================================

  onStart() {
    super.onStart()
    this.setVariable('isBot', true, 'boolean', 'public')
    this.facingMode = 'aim'
    this.acceleration = 14
    this._home = Array.from(this.worldPosition as ArrayLike<number>)
    this._model = this._findModel()
    this._animator = this._model?.animator ?? null
    this._brain = this._findBrain()
    if (this._brain) {
      this._brain.autoAcquire = false
      this._brain.perception = { ...this._brain.perception, range: this.sightRange, fieldOfView: this.sightAngle, memorySpan: 8, reactionTime: 0.2 }
    }
    this._equip()
    this.state = 'patrol'
    this._pickPatrol()
    // Skill reads as a spread of the bot's own reaction time, so a scene's bots are not clones.
    this.reactionSeconds *= 1.35 - this.skill * 0.7
  }

  onDespawn() {
    super.onDespawn()
  }

  private _findModel(): ModelNode | null {
    let found: ModelNode | null = null
    const visit = (n: Node) => {
      for (const c of n.children) {
        if (!found && c instanceof ModelNode && (c as any).animator) { found = c; return }
        if (!found) visit(c)
      }
    }
    visit(this)
    return found
  }

  private _findBrain(): any {
    for (const c of this.children) if ((c as any).nodeType === 'controller') return c
    return null
  }

  /** Show the weapon named by `weapon`, hide the others; the muzzle is the shown one's `Muzzle`. */
  private _equip(): void {
    const group = this.getChildByName('Weapons')[0]
    this._weapons = group ? findByVariable(group, 'fpsWeapon') : []
    this._muzzle = null
    for (const w of this._weapons) {
      const on = w.getVariable('fpsWeapon') === this.weapon
      w.visible = on
      if (on) this._muzzle = findDescendant(w, 'Muzzle')
    }
  }

  protected muzzleWorld(origin: number[]): number[] {
    const m = this._muzzle as any
    if (m?.worldPosition) { const p = m.worldPosition; return [p[0], p[1], p[2]] }
    return origin
  }

  // =================================================================================================
  // The frame
  // =================================================================================================

  onUpdate(delta: number) {
    this._time += delta
    this._stateTime += delta
    if (this.isDead) { this._deadFrame(); return }
    const gm = manager()
    const intent = this.drive()
    intent.sprint = false
    if (gm?.matchOver) { this._stand(intent); return }

    this._perceive(delta)
    this._think(delta)
    this._act(intent, delta)
    // The controller's pathing has written this frame's move; the speed it walks at is this script's call.
    if (this.navMode === 1) { intent.speedScale = this._speedScale; intent.sprint = this._sprint }

    if (this._sinceCombat > 6 && this.hp < this.maxHp) this.hp = Math.min(this.maxHp, this.hp + this.regenPerSecond * delta)
    this._animator?.setBool('Crouch', this.isCrouching)
  }

  /** Stand still, facing as before. */
  private _stand(intent: any): void {
    intent.move[0] = 0
    intent.move[1] = 0
    this.navMode = 0
  }

  // ----- sense -------------------------------------------------------------------------------------

  private _perceive(delta: number): void {
    this._losTimer -= delta
    const self = this.worldPosition
    let best: any = null
    let bestD = Infinity
    let visible = false
    const brain = this._brain
    if (brain) {
      for (const s of brain.sightings ?? []) {
        const other: any = this.scene?.getNodeById(s.id)
        if (!other || !other.getVariable?.('fpsCombatant') || other.isDead || !hostile(this, other)) continue
        const keep = other === this._target && s.timeSinceSeen <= brain.perception.memorySpan
        if (!s.noticed && !keep) continue
        const d = distance3(self, other.worldPosition)
        if (s.visible && s.noticed) {
          if (d < bestD) { best = other; bestD = d; visible = true }
        } else if (keep && !best) { best = other; bestD = d }
      }
    }
    const hadTarget = !!this._target
    if (best) {
      this._target = best
      if (visible) {
        if (!this._sees) this._noticedAt = this._time
        this._seenAt = this._time
        const p = best.worldPosition
        this._lastKnown = [p[0], p[1], p[2]]
      }
    } else if (this._target && (this._target.isDead || this._time - this._seenAt > 8)) {
      this._target = null
    }
    this._sees = visible
    if (visible) this._sinceCombat = 0
    else this._sinceCombat += delta
    if (hadTarget && !this._target && this._lastKnown) { this._alert = this._lastKnown; this._alertUntil = this._time + 12 }
    this.hasThreat = !!this._target
  }

  /** A shot was heard at `at`: look there unless already in a fight. */
  public hear(at: ArrayLike<number>, source: any): void {
    if (this.isDead || this._sees || this.state === 'engage' || this.state === 'cover' || this.state === 'retreat') return
    this._alert = [at[0], at[1], at[2]]
    this._alertUntil = this._time + 10
    if (this.state === 'patrol') this._enter('search')
  }

  /** A teammate called for help: come to `at` unless busy. Returns whether it is coming. */
  public respondTo(at: ArrayLike<number>, caller: any): boolean {
    if (this.isDead || this._sees || this.state === 'retreat') return false
    this._alert = [at[0], at[1], at[2]]
    this._alertUntil = this._time + 14
    this._enter('search')
    return true
  }

  // ----- think -------------------------------------------------------------------------------------

  private _enter(state: BotState): void {
    if (this.state === state) return
    this.state = state
    this._stateTime = 0
    this._inCover = false
    this._burst = 0
    if (state !== 'cover' && state !== 'retreat') this._coverPoint = null
    if (state === 'patrol') this._pickPatrol()
    if (state === 'engage') this._strafeUntil = 0
  }

  private _think(delta: number): void {
    const frac = this.hp / this.maxHp
    const recentlyHurt = this._time - this._hurtAt < 1.6
    const threat = this._target && (this._sees || this._time - this._seenAt < 3)
    if (this.state === 'retreat') {
      // Hold out of sight; recover, then come back. Cornered (the enemy close and shooting) it fights.
      if (!threat && this._stateTime > 6 && frac > this.retreatAt + 0.18) this._enter(frac < this.coverAt ? 'cover' : 'patrol')
      else if (threat && this._sees && distance3(this.worldPosition, this._target.worldPosition) < 7 && this._inCover) this._enter('engage')
      return
    }
    if (threat) {
      if (frac < this.retreatAt) { this._beginRetreat(); return }
      if ((frac < this.coverAt || (recentlyHurt && this.skill > 0.35)) && this.state !== 'cover') {
        if (this._time - this._calledAt > 18 && frac < this.coverAt) this._callForHelp()
        if (this._findCover()) { this._enter('cover'); return }
      }
      if (this.state === 'cover') {
        if (this._stateTime > this.coverSeconds * 2.5 && frac >= this.coverAt) this._enter('engage')
        return
      }
      this._enter('engage')
      return
    }
    // No threat.
    if (this.state === 'engage' || this.state === 'cover') {
      this._alert = this._lastKnown
      this._alertUntil = this._time + 12
      this._enter(this._alert ? 'search' : 'patrol')
    } else if (this.state === 'search' && this._time > this._alertUntil) this._enter('patrol')
  }

  private _beginRetreat(): void {
    if (this._time - this._calledAt > 18) this._callForHelp()
    this._enter('retreat')
    this._findCover(true)
  }

  private _callForHelp(): void {
    this._calledAt = this._time
    const at = this.worldPosition
    manager()?.callReinforcements?.(this.team, [at[0], at[1], at[2]], this)
  }

  private _findCover(far: boolean = false): boolean {
    const gm = manager()
    const from = this.worldPosition
    const threatAt = this._lastKnown ?? (this._target?.worldPosition as number[] | undefined)
    if (!gm || !threatAt) return false
    const cover = gm.bestCover([from[0], from[1], from[2]], threatAt, far ? 40 : 24)
    if (!cover) return false
    this._coverPoint = cover
    this._inCover = false
    return true
  }

  // ----- act ---------------------------------------------------------------------------------------

  private _act(intent: any, delta: number): void {
    switch (this.state) {
      case 'patrol': this._patrol(intent, delta); break
      case 'search': this._search(intent, delta); break
      case 'engage': this._engage(intent, delta); break
      case 'cover': this._cover(intent, delta, false); break
      case 'retreat': this._cover(intent, delta, true); break
    }
    // A reload takes the bot's hands and, in the open, ducks it.
    if (this._reloading > 0) {
      this._reloading -= delta
      if (this._reloading <= 0) {
        const spec = this.spec
        const take = Math.min(spec.mag - this.ammo, this.reserve)
        this.ammo += take
        this.reserve = Math.max(spec.mag, this.reserve - take)
      }
    }
    this.isCrouching = this._crouching || this._reloading > 0 && this.state !== 'engage'
  }

  private _go(point: number[], speed: number, sprint: boolean = false): void {
    this.goalPoint = point
    this.navMode = 1
    this._speedScale = speed
    this._sprint = sprint
    if (this._brain) this._brain.goalPoint = [point[0], point[1], point[2]]
  }

  private _speedScale: number = 1
  private _sprint: boolean = false

  private _patrol(intent: any, delta: number): void {
    this.facingMode = 'velocity'
    this._crouching = false
    const p = this.worldPosition
    if (this._patrolWait > 0) {
      this._patrolWait -= delta
      this._stand(intent)
      return
    }
    if (planarDistance(p, this.goalPoint) < 1.6 || this._stateTime > 25) {
      this._patrolWait = 1 + Math.random() * 3
      this._pickPatrol()
      this._stand(intent)
      return
    }
    this._go(this.goalPoint, this.patrolSpeedScale)
  }

  private _pickPatrol(): void {
    const ai = (this.scene as any)?.ai
    const mesh = ai?.navMeshFor?.(null)?.mesh
    const home = this._home
    for (let i = 0; i < 6; i++) {
      const a = Math.random() * Math.PI * 2, r = 6 + Math.random() * 16
      let pt = [home[0] + Math.sin(a) * r, home[1], home[2] + Math.cos(a) * r]
      if (mesh?.randomPoint) {
        const out = [0, 0, 0]
        mesh.randomPoint(out)
        if (planarDistance(out, home) < 40) pt = [out[0], out[1], out[2]]
      }
      this.goalPoint = pt
      return
    }
  }

  private _search(intent: any, delta: number): void {
    this._crouching = false
    const target = this._alert
    if (!target) { this._enter('patrol'); return }
    const p = this.worldPosition
    if (planarDistance(p, target) > 2.2 && this._stateTime < 20) {
      this.facingMode = 'velocity'
      this._go(target, 0.9, planarDistance(p, target) > 18)
      return
    }
    // Arrived: look round, slowly, then give up.
    this.navMode = 0
    this.facingMode = 'aim'
    intent.move[0] = 0; intent.move[1] = 0
    this._turn(intent, this._baseYaw() + Math.sin(this._stateTime * 1.1) * 110, 180 * delta)
    if (this._stateTime > 5.5 && this._time > this._alertUntil - 8) this._enter('patrol')
  }

  private _baseYaw(): number {
    if (this._alert) return yawTo(this.worldPosition, this._alert)
    return this._yawNow()
  }

  private _yawNow(): number {
    const f = this.worldForward
    return Math.atan2(f[0], f[2]) * 180 / Math.PI
  }

  /** Turn toward `yaw` at most `maxStep` degrees this frame, through the intent. */
  private _turn(intent: any, yaw: number, maxStep: number): void {
    const have = this._yawNow()
    const diff = angleDiff(yaw, have)
    intent.aimYaw = have + clamp(diff, -maxStep, maxStep)
    this.facingMode = 'aim'
  }

  // ----- engage ------------------------------------------------------------------------------------

  private _engage(intent: any, delta: number): void {
    const target = this._target
    if (!target) return
    const me = this.worldPosition
    const at = this._sees ? target.worldPosition : (this._lastKnown ?? target.worldPosition)
    const dist = planarDistance(me, at)
    const spec = this.spec
    const yawToTarget = yawTo(me, at)
    const desired = clamp(spec.botRange * 0.45, 7, 22)

    // Out of sight but remembered: go and look rather than stand shooting at a wall.
    if (!this._sees && this._time - this._seenAt > 1.2) {
      this.facingMode = 'velocity'
      this._go([at[0], at[1], at[2]], 1, true)
      return
    }

    this._turn(intent, yawToTarget, 540 * delta * (0.5 + this.skill))
    if (dist > spec.botRange * 0.9) {
      // Too far to shoot: close the distance on the nav mesh at a run.
      this._crouching = false
      this._go([at[0], at[1], at[2]], 1)
      this.facingMode = 'velocity'
      return
    }

    // In range: hold a distance and strafe, standing or crouching; the controller does not move the body.
    this.navMode = 2
    this._strafeUntil -= delta
    if (this._strafeUntil <= 0) {
      this._strafeUntil = 1 + Math.random() * 2.2
      this._strafe = Math.random() < 0.5 ? -1 : 1
      // A crouch spell at long range makes a smaller target; at close range it keeps moving.
      this._crouching = dist > 13 && Math.random() < this.crouchChance
      if (this._crouching) this._strafeUntil += 1.2
    }
    const toward = [Math.sin(yawToTarget * Math.PI / 180), Math.cos(yawToTarget * Math.PI / 180)]
    let mx = 0, mz = 0, scale = 0
    if (!this._crouching) {
      if (dist < desired - 3) { mx = -toward[0]; mz = -toward[1]; scale = 0.7 }
      else if (dist > desired + 4) { mx = toward[0]; mz = toward[1]; scale = 0.8 }
      else { mx = toward[1] * this._strafe; mz = -toward[0] * this._strafe; scale = 0.75 }
    }
    if (scale > 0) { setMoveWorld(intent, mx, mz); intent.speedScale = scale } else { intent.move[0] = 0; intent.move[1] = 0 }

    this._shoot(intent, delta, target)
  }

  /** Fire when it faces the target, has seen it long enough and has rounds; reload when dry. */
  private _shoot(intent: any, delta: number, target: any): void {
    if (this._reloading > 0) return
    const spec = this.spec
    if (this.ammo <= 0) { this._startReload(); return }
    if (!this._sees || this._time - this._noticedAt < this.reactionSeconds) return
    const eye = this._eye()
    const aimAt = target.chest
    const dx = aimAt[0] - eye[0], dy = aimAt[1] - eye[1], dz = aimAt[2] - eye[2]
    const len = Math.hypot(dx, dy, dz) || 1
    if (Math.abs(angleDiff(Math.atan2(dx, dz) * 180 / Math.PI, this._yawNow())) > 9) return
    if (this._time < this._nextShot) return
    if (this._burst <= 0) {
      this._burst = Math.round(spec.botBurst[0] + Math.random() * (spec.botBurst[1] - spec.botBurst[0]))
    }
    this._fireOnce(eye, [dx / len, dy / len, dz / len], len)
    this._burst--
    const interval = 60 / (spec.rpm * this.fireRateScale)
    this._nextShot = this._time + interval + (this._burst <= 0 ? (0.5 + Math.random() * 1.2) * (1.4 - this.skill) : 0)
  }

  private _eye(): number[] {
    const p = this.worldPosition
    return [p[0], p[1] + this.eyeOffset, p[2]]
  }

  private _fireOnce(eye: number[], dir: number[], dist: number): void {
    const spec = this.spec
    this.ammo--
    // Worse aim at range and when moving; the skill narrows it. A degree and a half at 20 m at mid skill.
    const cone = (spec.hipSpread * 0.55 + dist * 0.045) * (1.7 - this.skill * 1.3) * (this._crouching ? 0.7 : 1)
    this.fireHitscan(eye, dir, cone, this.damageScale)
    this._muzzleFlash()
    this._animator?.setTrigger?.('Fire')
  }

  private _muzzleFlash(): void {
    const at = this.muzzleWorld(this._eye())
    this.spawnFx('FPS Muzzle Flash', at, [0, this._yawNow(), 0])
    playCue(this, 'Shot')
  }

  private _startReload(): void {
    if (this.reserve <= 0) { this.reserve = this.spec.reserve }
    this._reloading = this.spec.reloadSeconds * (1.2 - this.skill * 0.3)
    this._burst = 0
  }

  // ----- cover / retreat ---------------------------------------------------------------------------

  private _cover(intent: any, delta: number, retreat: boolean): void {
    const cover = this._coverPoint
    const me = this.worldPosition
    if (!cover) {
      // Nowhere to hide. A retreat with no cover runs away from the threat; a cover state just fights.
      if (retreat && this._lastKnown) {
        const away = yawTo(this._lastKnown, me)
        const goal = [me[0] + Math.sin(away * Math.PI / 180) * 18, me[1], me[2] + Math.cos(away * Math.PI / 180) * 18]
        this.facingMode = 'velocity'
        this._crouching = false
        this._go(goal, 1, true)
      } else if (!retreat) this._engage(intent, delta)
      if (this._stateTime > 1.5 && !this._findCover(retreat) && !retreat) this._enter('engage')
      return
    }
    if (!this._inCover) {
      this.facingMode = 'velocity'
      this._crouching = false
      this._go(cover, 1, true)
      if (planarDistance(me, cover) < 1.4) { this._inCover = true; this._stateTime = 0; this._wait = this.coverSeconds * (0.7 + Math.random() * 0.6) }
      else if (this._stateTime > 14) { this._coverPoint = null }
      return
    }
    // In cover: stay low and still, facing where the threat is; reload; look up and shoot in turn.
    this.navMode = 0
    intent.move[0] = 0; intent.move[1] = 0
    const look = this._lastKnown ? yawTo(me, this._lastKnown) : this._yawNow()
    this._turn(intent, look, 360 * delta)
    this._wait -= delta
    if (this.ammo < this.spec.mag * 0.5 && this._reloading <= 0 && this.ammo < this.spec.mag) this._startReload()
    const peek = !retreat && this._wait <= 0 && this._reloading <= 0
    this._crouching = !peek
    if (peek) {
      // Up from behind it: shoot while the threat is in sight, then back down.
      if (this._sees && this._target) this._shoot(intent, delta, this._target)
      if (this._stateTime > this.coverSeconds + 3 + this.skill * 3) { this._stateTime = 0; this._wait = this.coverSeconds * (0.8 + Math.random() * 0.8) }
    }
    if (retreat) this.hp = Math.min(this.maxHp, this.hp + this.regenPerSecond * 0.8 * delta)
  }

  // =================================================================================================
  // Hurt, dead
  // =================================================================================================

  protected onHurt(damage: number, from: Node | null, zone: string): void {
    this._hurtAt = this._time
    this._sinceCombat = 0
    const shooter: any = combatantOf(from)
    if (shooter && hostile(this, shooter)) {
      // Whoever shot it is now where it looks; with no target, it turns and goes to see.
      if (!this._target || !this._sees) {
        this._target = shooter
        this._noticedAt = this._time - this.reactionSeconds * 0.4
        const p = shooter.worldPosition
        this._lastKnown = [p[0], p[1], p[2]]
        this._seenAt = this._time
      }
    }
  }

  protected onDeath(killer: any, zone: string, dir?: ArrayLike<number>): void {
    this.state = 'dead'
    this.navMode = 0
    this.hasThreat = false
    this.facingMode = 'none'
    // Which clip: from where the bullet came, relative to the way the bot faces. Mostly the matching
    // one, sometimes any of them - a random death - and a crouching bot always falls its own way.
    const clip = this._pickDeath(killer, zone, dir)
    const index = DEATHS.indexOf(clip)
    this._animator?.setTrigger?.(`Die${index}`)
    const info = this._animator?.triggerInfo?.(`Die${index}`)
    const seconds = info?.seconds && info.seconds > 0 ? info.seconds : 3
    this.after(seconds * this.ragdollAt, () => this._ragdoll(dir))
    this.after(this.corpseSeconds, () => this.remove({ fade: 1.2 }))
    playCue(this, 'Death')
  }

  private _pickDeath(killer: any, zone: string, dir?: ArrayLike<number>): string {
    if (this.isCrouching) return Math.random() < 0.6 ? 'DeathCrouchingHeadshotFront' : DEATHS[Math.floor(Math.random() * 5)]
    const head = zone === 'head'
    const pool = ['DeathFromTheFront', 'DeathFromTheBack', 'DeathFromRight']
    if (head) pool.push('DeathFromFrontHeadshot', 'DeathFromBackHeadshot')
    let matched: string | null = null
    if (killer) {
      // The bearing of the shooter relative to where this bot faces: 0 ahead, +-180 behind.
      const rel = angleDiff(yawTo(this.worldPosition, killer.worldPosition), this._yawNow())
      if (Math.abs(rel) < 55) matched = head ? 'DeathFromFrontHeadshot' : 'DeathFromTheFront'
      else if (Math.abs(rel) > 125) matched = head ? 'DeathFromBackHeadshot' : 'DeathFromTheBack'
      else matched = 'DeathFromRight'
    }
    return matched && Math.random() < 0.55 ? matched : pool[Math.floor(Math.random() * pool.length)]
  }

  private _ragdoll(dir?: ArrayLike<number>): void {
    const physics = this.scene?.physics as any
    if (!physics?.startRagdoll || !this._model) return
    try {
      const push = dir ? [dir[0] * 2.2, 0.6, dir[2] * 2.2] : [0, 0, 0]
      physics.startRagdoll(this._model, { impulse: push })
    } catch (e) {
      Logger.warn('FPS: ragdoll failed on ' + this.name + ': ' + e, 'Script')
    }
  }

  private _deadFrame(): void {
    this.navMode = 0
    const intent = this.drive()
    intent.move[0] = 0
    intent.move[1] = 0
  }

  /** A fresh life (the manager moves the body): stand up, forget the fight. */
  public resetForRespawn(): void {
    super.resetForRespawn()
    this.state = 'patrol'
    this._target = null
    this._lastKnown = null
    this._alert = null
    this._enter('patrol')
  }
}

import { Node, UIProgressBarNode, UIRootNode, UITextNode } from 'cleo'
import { WEAPONS, angleDiff, clamp, manager, yawTo } from '@/FPS/Scripts/FpsShared'

/**
 * FPS example — the player's HUD. Attach to the `HUD` node, a screen-space UI Root that is a CHILD of the
 * player (in the Player template): it reads its parent, so a second player would bring a second HUD.
 *
 * It finds its widgets by NAME once (missing ones are skipped, so restyle or rebuild it freely as long as
 * the names stay) and writes them every frame:
 *
 *   CrossTop/Bottom/Left/Right, CrossDot   the crosshair; the arms open with the weapon's spread
 *   HitMarker, HitMarkerKill               a hit; red on a kill; the head shot's is larger
 *   Health, HealthText                     hp
 *   Ammo, Reserve, WeaponName, Reloading   the weapon in hand
 *   Score, Timer, Feed, Mode               the match (from the Game Manager, when the scene has one)
 *   Message, SubMessage                    centre text: "YOU DIED", the respawn count, the winner
 *   HitFront/Back/Left/Right, Vignette     where damage came from, and the red edge at low health
 */
export default class FpsHudNode extends UIRootNode {
  /** Pixels of crosshair gap per degree of spread, at the hip field of view. */
  public pixelsPerDegree: number = 11
  public crosshairGap: number = 5
  public crosshairLength: number = 9
  public hitMarkerSeconds: number = 0.22
  public indicatorSeconds: number = 1.4
  /** Hide the crosshair while aimed (the sights are the aim). */
  public hideCrosshairAimed: boolean = true

  private _player: any = null
  private _w: Record<string, any> = {}
  private _gap: number = -1

  onStart() {
    for (let n: Node | null = this.parent; n; n = n.parent) if ((n as any).getVariable?.('fpsCombatant') || (n as any).team) { this._player = n; break }
    for (const name of ['CrossTop', 'CrossBottom', 'CrossLeft', 'CrossRight', 'CrossDot', 'HitMarker', 'HitMarkerKill',
      'Health', 'HealthText', 'Ammo', 'Reserve', 'WeaponName', 'Reloading', 'Score', 'Timer', 'Feed', 'Mode',
      'Message', 'SubMessage', 'HitFront', 'HitBack', 'HitLeft', 'HitRight', 'Vignette', 'Crosshair', 'Ammunition'])
      this._w[name] = this._find(name)
    this._show('HitMarker', false)
    this._show('HitMarkerKill', false)
  }

  onUpdate(delta: number) {
    const p = this._player
    if (!p) return
    const gm = manager()
    const t = p._time ?? 0

    // ----- crosshair
    const aimed = this.hideCrosshairAimed && p.ads > 0.6
    this._show('Crosshair', !p.isDead && !aimed && !p.sprinting)
    const gap = Math.round(this.crosshairGap + p.spreadNow * this.pixelsPerDegree)
    if (gap !== this._gap) {
      this._gap = gap
      const len = this.crosshairLength
      this._setRect('CrossTop', [-1, -(gap + len)], [1, -gap])
      this._setRect('CrossBottom', [-1, gap], [1, gap + len])
      this._setRect('CrossLeft', [-(gap + len), -1], [-gap, 1])
      this._setRect('CrossRight', [gap, -1], [gap + len, 1])
    }
    const hm = t - p.hitMarkerAt
    const hit = hm >= 0 && hm < this.hitMarkerSeconds
    this._show('HitMarker', hit && !p.hitMarkerKill)
    this._show('HitMarkerKill', hit && p.hitMarkerKill)
    if (hit) this._setOpacity(p.hitMarkerKill ? 'HitMarkerKill' : 'HitMarker', 1 - hm / this.hitMarkerSeconds)

    // ----- health and the weapon
    this._bar('Health', p.hp, p.maxHp)
    this._text('HealthText', String(Math.ceil(p.hp)))
    const spec = WEAPONS[p.weapon]
    this._show('Ammunition', !p.isDead)
    this._text('Ammo', String(p.ammo))
    this._text('Reserve', '/ ' + p.reserve)
    this._text('WeaponName', spec ? spec.name.toUpperCase() : '')
    this._text('Reloading', p.reloading ? 'RELOADING' : p.ammo <= 0 && !p.isDead ? 'EMPTY' : p.ammo <= Math.ceil((spec?.mag ?? 30) * 0.25) && !p.isDead ? 'LOW AMMO' : '')

    // ----- damage direction, and the edge of the screen at low health
    const since = p._time - p.lastHitAt
    if (since < this.indicatorSeconds && p.lastHitFrom) {
      const rig = p._rig
      const yaw = rig ? rig.yaw : 0
      const rel = angleDiff(yawTo(p.worldPosition, p.lastHitFrom), yaw)
      const k = 1 - since / this.indicatorSeconds
      // Front is 0; the screen's right is a NEGATIVE turn.
      const front = Math.cos(rel * Math.PI / 180), side = Math.sin(rel * Math.PI / 180)
      this._setOpacity('HitFront', Math.max(0, front) * k)
      this._setOpacity('HitBack', Math.max(0, -front) * k)
      this._setOpacity('HitLeft', Math.max(0, side) * k)
      this._setOpacity('HitRight', Math.max(0, -side) * k)
    } else for (const n of ['HitFront', 'HitBack', 'HitLeft', 'HitRight']) this._setOpacity(n, 0)
    const low = clamp(1 - p.hp / (p.maxHp * 0.5), 0, 1)
    this._setOpacity('Vignette', p.isDead ? 0.7 : low * 0.75)

    // ----- the match
    if (gm) {
      const standings = gm.standings()
      const mine = standings.find((s: any) => s.team === p.team)
      const best = standings.find((s: any) => s.team !== p.team)
      this._text('Score', gm.mode === 'ffa'
        ? `${mine?.score ?? 0}`  + (best ? `   best ${best.score}` : '')
        : `${gm.teamName(p.team)} ${mine?.score ?? 0}   -   ${best ? gm.teamName(best.team) : ''} ${best?.score ?? 0}`)
      this._text('Timer', gm.timeLimit > 0 ? this._clock(gm.timeLeft) : '')
      this._text('Feed', gm.feed.join('\n'))
      this._text('Mode', gm.scoreLimit > 0 ? `first to ${gm.scoreLimit}` : '')
    }
    let message = '', sub = ''
    if (gm?.matchOver) { message = gm.message; sub = 'next match shortly' }
    else if (p.isDead) { message = 'YOU DIED'; sub = p.respawnIn > 0.05 ? `respawn in ${Math.ceil(p.respawnIn)}` : '' }
    this._text('Message', message)
    this._text('SubMessage', sub)
  }

  private _clock(seconds: number): string {
    const s = Math.max(0, Math.ceil(seconds))
    return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`
  }

  private _bar(name: string, value: number, max: number): void {
    const bar = this._w[name] as UIProgressBarNode
    if (!bar) return
    if (bar.max !== max) bar.max = Math.max(1, max)
    bar.value = Math.max(0, value)
  }

  private _text(name: string, value: string): void {
    const node = this._w[name] as UITextNode
    if (node && node.text !== value) node.text = value
  }

  private _show(name: string, on: boolean): void {
    const node = this._w[name]
    if (node && node.visible !== on) node.visible = on
  }

  private _setOpacity(name: string, value: number): void {
    const node = this._w[name]
    if (node && Math.abs(node.opacity - value) > 0.01) node.opacity = value
  }

  private _setRect(name: string, min: number[], max: number[]): void {
    const node = this._w[name]
    if (!node) return
    node.offsetMin = min
    node.offsetMax = max
  }

  private _find(name: string): Node | null {
    const walk = (node: Node): Node | null => {
      for (const child of node.children) {
        if (child.name === name) return child
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(this)
  }
}

import { Node } from 'cleo'

/**
 * FPS example — a fire-and-forget effect (muzzle flash, impact, blood). Attach to the root of an effect
 * template. On start it plays every Particle System child (a `burstCount` > 0 bursts that many instead),
 * fades every point light child over `lifetime`, and removes itself when that time is up.
 *
 * The look is the template's particle systems; this script only owns the lifetime.
 */
export default class FpsFxNode extends Node {
  public lifetime: number = 0.6
  /** Particles per child system on start. 0 leaves them to their own spawn rate and bursts. */
  public burstCount: number = 0
  /** Fade the lights to nothing over `lifetime` (a flash's light falls off fast: this squares it). */
  public lightFalloff: number = 2

  private _age: number = 0
  private _lights: any[] = []
  private _intensities: number[] = []

  onStart() {
    this._age = 0
    const walk = (node: Node) => {
      for (const child of node.children) {
        const c = child as any
        if (child.nodeType === 'particleSystem') {
          c.play?.()
          if (this.burstCount > 0) c.burst?.(this.burstCount)
        }
        if (child.nodeType === 'light' && c.light) {
          this._lights.push(c.light)
          this._intensities.push(c.light.intensity)
        }
        walk(child)
      }
    }
    walk(this)
  }

  onUpdate(delta: number) {
    this._age += delta
    const k = Math.pow(Math.max(0, 1 - this._age / Math.max(0.01, this.lifetime)), this.lightFalloff)
    for (let i = 0; i < this._lights.length; i++) this._lights[i].intensity = this._intensities[i] * k
    if (this._age >= this.lifetime) this.remove({ immediate: true })
  }
}

import { Node } from 'cleo'
import { clamp } from '@/FPS/Scripts/FpsShared'

/**
 * FPS example — a bullet hole. Attach to the root of a template whose children are Decal nodes; the shooter
 * (FpsCombatant) instantiates one at the hit, turned so its decals project straight into the surface. On
 * start each decal takes a random spin about its own axis and a random size; after `lifetime` they fade over
 * `fadeSeconds` and the template removes itself. The Game Manager also removes the oldest past its limit.
 */
export default class FpsDecalNode extends Node {
  public lifetime: number = 45
  public fadeSeconds: number = 6
  public minSize: number = 0.8
  public maxSize: number = 1.2

  private _age: number = 0
  private _decals: any[] = []

  onStart() {
    this._decals = this.children.filter(c => c.nodeType === 'decal')
    const scale = this.minSize + Math.random() * Math.max(0, this.maxSize - this.minSize)
    for (const d of this._decals) {
      d.setRotation([0, Math.random() * 360, 0])
      const s = d.size
      d.size = [s[0] * scale, s[1], s[2] * scale]
    }
  }

  onUpdate(delta: number) {
    this._age += delta
    const k = clamp((this.lifetime - this._age) / Math.max(0.01, this.fadeSeconds), 0, 1)
    for (const d of this._decals) if (Math.abs(d.opacity - k) > 0.01) d.opacity = k
    if (this._age >= this.lifetime) this.remove({ immediate: true })
  }
}

import { Node } from 'cleo'

/**
 * FPS example — a tracer round. The shooter instantiates one at the muzzle, turned along the shot, and sets
 * `tracerLength`, the distance to what the bullet hit. It is a thin glowing streak (the template's mesh,
 * along +Z) that flies from the muzzle to the hit at `speed` and is gone: the first `trail` metres of it
 * are the streak's own length, so it never stretches past the shot.
 */
export default class FpsTracerNode extends Node {
  /** Set by the shooter: distance from the muzzle to the end of the shot. */
  public tracerLength: number = 0
  public speed: number = 420
  /** Length of the streak, metres. */
  public trail: number = 6

  private _flown: number = 0
  private _start: number[] | null = null
  private _dir: number[] = [0, 0, 1]

  onUpdate(delta: number) {
    if (!this._start) {
      this.updateTransforms(this.parent ? this.parent.worldTransform : null)
      const p = this.worldPosition
      this._start = [p[0], p[1], p[2]]
      const f = this.worldForward
      this._dir = [f[0], f[1], f[2]]
      // The streak is shortened to the shot when the shot is shorter.
      const s = Math.min(1, Math.max(0.05, this.tracerLength / Math.max(1, this.trail)))
      this.setScale([1, 1, s])
    }
    this._flown += this.speed * delta
    const end = this.tracerLength
    if (this._flown >= end + this.trail * 0.2) { this.remove({ immediate: true }); return }
    const at = Math.min(this._flown, Math.max(0, end - this.trail * 0.5))
    this.setWorldPosition([this._start[0] + this._dir[0] * at, this._start[1] + this._dir[1] * at, this._start[2] + this._dir[2] * at])
  }
}

import { Node } from 'cleo'

/**
 * FPS example — a marker the Game Manager reads. Attach to a Spawn Point or Cover Point template:
 *
 *   kind 'spawn'   a place fighters start and respawn; its facing (the node's +Z) is the way they look
 *   kind 'cover'   a spot a bot may crouch behind; the manager checks it is out of a threat's sight
 *
 * It only sets the variable the manager finds it by (`fpsSpawn` / `fpsCover`). The node is invisible in
 * play; the template draws a small gizmo for the editor.
 */
export default class FpsMarkerNode extends Node {
  public kind: 'spawn' | 'cover' = 'spawn'

  onStart() {
    this.setVariable(this.kind === 'cover' ? 'fpsCover' : 'fpsSpawn', true, 'boolean', 'public')
  }
}
